        "Actor" text NOT NULL,
        "Status" text NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        "LeaseUntil" timestamp with time zone,
        "LeaseToken" uuid,
        "Attempts" integer NOT NULL,
        "CompletedAt" timestamp with time zone,
        "Error" text,
        "ResultJson" text,
        CONSTRAINT "PK_Jobs" PRIMARY KEY ("Id")
